CREATE PROCEDURE dbo.usp_GenerarIDDepositoPlazo
    @NuevoID NVARCHAR(20) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Anio INT = YEAR(SYSDATETIME());
    DECLARE @Mes  INT = MONTH(SYSDATETIME());
    DECLARE @N    INT;

    MERGE dbo.SecuenciaDPF AS target
    USING (SELECT @Anio AS A, @Mes AS M) AS source ON (target.Anio = source.A AND target.Mes = source.M)
    WHEN MATCHED THEN UPDATE SET UltimoN = UltimoN + 1
    WHEN NOT MATCHED THEN INSERT (Anio, Mes, UltimoN) VALUES (@Anio, @Mes, 1);

    SELECT @N = UltimoN FROM dbo.SecuenciaDPF WHERE Anio = @Anio AND Mes = @Mes;
    SET @NuevoID = 'DPF-' + CAST(@Anio AS NVARCHAR(4)) + RIGHT('0' + CAST(@Mes AS NVARCHAR(2)), 2) + '-' + RIGHT('000' + CAST(@N AS NVARCHAR(4)), 4);
END

-- 5. Recrear dbo.usp_GuardarCroquisTrabajo con parámetro RutaImagen
CREATE   PROCEDURE dbo.usp_GuardarCroquisTrabajo
    @SOCIOID BIGINT,
    @ImagenCroquis VARBINARY(MAX),
    @Descripcion NVARCHAR(500),
    @RutaImagen NVARCHAR(250) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM dbo.SocioCroquisTrabajo WHERE SOCIOID = @SOCIOID)
    BEGIN
        UPDATE dbo.SocioCroquisTrabajo
        SET 
            ImagenCroquis = @ImagenCroquis,
            Descripcion = @Descripcion,
            RutaImagen = COALESCE(@RutaImagen, RutaImagen),
            FechaCaptura = SYSDATETIME()
        WHERE SOCIOID = @SOCIOID;
    END
    ELSE
    BEGIN
        INSERT INTO dbo.SocioCroquisTrabajo (
            SOCIOID,
            ImagenCroquis,
            Descripcion,
            RutaImagen
        )
        VALUES (
            @SOCIOID,
            @ImagenCroquis,
            @Descripcion,
            @RutaImagen
        );
    END;
END;

